/* EARTHUS V2 — GK2A official L2 CTH relief + observed GMGSI appearance. */
const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));
async function imageFromBlob(blob){const url=URL.createObjectURL(blob);try{const image=new Image();image.crossOrigin='anonymous';await new Promise((ok,no)=>{image.onload=ok;image.onerror=()=>no(new Error('GK2A_CTH_OBSERVED_IMAGE_DECODE'));image.src=url});return image}finally{URL.revokeObjectURL(url)}}
function observedCanvas(image,meta){const cv=document.createElement('canvas');cv.width=image.naturalWidth||image.width;cv.height=image.naturalHeight||image.height;const cx=cv.getContext('2d',{willReadFrequently:true});if(!cx)throw new Error('GK2A_CTH_CANVAS_CONTEXT');cx.drawImage(image,0,0);const px=cx.getImageData(0,0,cv.width,cv.height),d=px.data;if(meta.format==='la8')for(let i=0;i<d.length;i+=4){const l=Math.round(138+d[i]*117/255);d[i]=d[i+1]=d[i+2]=l;d[i+3]=Math.round(238*Math.pow(d[i+3]/255,.82))}else for(let i=0;i<d.length;i+=4){d[i]=d[i+1]=d[i+2]=255;d[i+3]=Math.round(238*Math.pow(d[i]/255,.82))}cx.putImageData(px,0,0);return cv}
async function loadObserved(base){const mr=await fetch(`${base}/meta.json?t=${Date.now()}`,{cache:'no-cache'});if(!mr.ok)throw new Error(`GK2A_CTH_OBSERVED_META_${mr.status}`);const meta=await mr.json(),south=Number(meta?.south),north=Number(meta?.north);if(!meta?.time||!Number.isFinite(south)||!Number.isFinite(north)||north<=south)throw new Error('GK2A_CTH_OBSERVED_META_INVALID');const ir=await fetch(`${base}/global.png?t=${encodeURIComponent(meta.time)}`,{cache:'no-cache'});if(!ir.ok)throw new Error(`GK2A_CTH_OBSERVED_IMAGE_${ir.status}`);return Object.freeze({canvas:observedCanvas(await imageFromBlob(await ir.blob()),meta),meta:Object.freeze({time:meta.time,south,north,source:'NOAA_NESDIS_GMGSI',truthClass:'OBSERVED_2D_APPEARANCE'})})}
export class Gk2aCthReliefRuntime{
 constructor({viewer,Cesium,baseUrl='/clouds/gk2a/cth',observedBaseUrl='/clouds'}={}){if(!viewer||viewer.isDestroyed?.())throw new Error('GK2A_CTH_VIEWER_REQUIRED');this.viewer=viewer;this.C=Cesium||globalThis.Cesium;this.baseUrl=baseUrl.replace(/\/$/,'');this.observedBaseUrl=observedBaseUrl.replace(/\/$/,'');this.primitive=null;this.manifest=null;this.visible=false;this.generation=0}
 async load({force=false}={}){const generation=++this.generation;if(this.primitive&&!force)return this.manifest;const mr=await fetch(`${this.baseUrl}/manifest.json?t=${Date.now()}`,{cache:'no-cache'});if(!mr.ok)throw new Error(`GK2A_CTH_MANIFEST_${mr.status}`);const m=await mr.json();if(m.ready!==true||m.synthetic===true||m.truthClass!=='OBSERVED_DERIVED_OFFICIAL_L2'||m.units!=='m')throw new Error('GK2A_CTH_MANIFEST_TRUTH_GATE');const gr=await fetch(new URL(m.gridUrl,`${location.origin}${this.baseUrl}/`).href,{cache:'no-cache'});if(!gr.ok)throw new Error(`GK2A_CTH_GRID_${gr.status}`);const g=await gr.json(),observed=await loadObserved(this.observedBaseUrl);if(generation!==this.generation)return null;this.#validate(g,m);this.#destroy();this.primitive=this.#build(g,observed);this.primitive.show=this.visible;this.manifest=Object.freeze({...m,appearanceTruthClass:'OBSERVED_2D_GMGSI_DRAPED_ON_OBSERVED_CTH',appearanceSource:'NOAA_NESDIS_GMGSI',appearanceValidAt:observed.meta.time});this.viewer.scene.requestRender();return this.manifest}
 #validate(g,m){const n=g.width*g.height;if(g.synthetic===true||g.truthClass!=='OBSERVED_DERIVED_OFFICIAL_L2'||g.units!=='m')throw new Error('GK2A_CTH_GRID_TRUTH_GATE');for(const k of['longitude','latitude','heightM','valid'])if(!Array.isArray(g[k])||g[k].length!==n)throw new Error(`GK2A_CTH_GRID_${k.toUpperCase()}_SHAPE`);if(g.width!==m.width||g.height!==m.height||n<4||n>100000)throw new Error('GK2A_CTH_GRID_DIMENSION_GATE')}
 #build(g,o){const C=this.C,n=g.width*g.height,pos=new Float64Array(n*3),norm=new Float32Array(n*3),st=new Float32Array(n*2),valid=new Uint8Array(n),span=Math.max(1e-6,o.meta.north-o.meta.south),scratch=new C.Cartesian3();let count=0;for(let i=0;i<n;i++){const lon=Number(g.longitude[i]),lat=Number(g.latitude[i]),h=Number(g.heightM[i]),ok=g.valid[i]===1&&Number.isFinite(lon)&&Number.isFinite(lat)&&Number.isFinite(h)&&lat>=-90&&lat<=90&&lon>=-180&&lon<=180&&h>=0&&h<=25000;valid[i]=ok?1:0;const p=C.Cartesian3.fromDegrees(ok?lon:0,ok?lat:0,ok?h:0);pos[i*3]=p.x;pos[i*3+1]=p.y;pos[i*3+2]=p.z;C.Ellipsoid.WGS84.geodeticSurfaceNormal(p,scratch);norm[i*3]=scratch.x;norm[i*3+1]=scratch.y;norm[i*3+2]=scratch.z;st[i*2]=ok?clamp((lon+180)/360):0;st[i*2+1]=ok?clamp((lat-o.meta.south)/span):0;if(ok)count++}if(count<100)throw new Error('GK2A_CTH_VALID_CELL_GATE');const idx=[],w=g.width,hg=g.height,V=i=>valid[i]===1;for(let y=0;y<hg-1;y++)for(let x=0;x<w-1;x++){const a=y*w+x,b=a+1,c=a+w,d=c+1;if(V(a)&&V(b)&&V(c))idx.push(a,c,b);if(V(b)&&V(c)&&V(d))idx.push(b,c,d)}if(idx.length<300)throw new Error('GK2A_CTH_TRIANGLE_GATE');const geometry=new C.Geometry({attributes:{position:new C.GeometryAttribute({componentDatatype:C.ComponentDatatype.DOUBLE,componentsPerAttribute:3,values:pos}),normal:new C.GeometryAttribute({componentDatatype:C.ComponentDatatype.FLOAT,componentsPerAttribute:3,values:norm}),st:new C.GeometryAttribute({componentDatatype:C.ComponentDatatype.FLOAT,componentsPerAttribute:2,values:st})},indices:C.IndexDatatype.createTypedArray(n,idx),primitiveType:C.PrimitiveType.TRIANGLES,boundingSphere:C.BoundingSphere.fromVertices(pos)}),material=C.Material.fromType('Image',{image:o.canvas,repeat:new C.Cartesian2(1,1)}),appearance=new C.MaterialAppearance({material,materialSupport:C.MaterialAppearance.MaterialSupport.TEXTURED,flat:false,faceForward:true,translucent:true,closed:false});return this.viewer.scene.primitives.add(new C.Primitive({geometryInstances:new C.GeometryInstance({geometry}),appearance,allowPicking:false,asynchronous:false,show:false}))}
 setVisible(show){this.visible=!!show;if(this.primitive)this.primitive.show=this.visible;this.viewer.scene.requestRender()}
 async show(){this.visible=true;if(!this.primitive)await this.load();if(this.primitive)this.primitive.show=true;this.viewer.scene.requestRender();return this.manifest}
 hide(){this.setVisible(false)}
 #destroy(){if(this.primitive){try{this.viewer.scene.primitives.remove(this.primitive)}catch(_){}this.primitive=null}}
 dispose(){this.generation++;this.#destroy();this.manifest=null;this.visible=false}
}
